 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Detect the uniform separator.
    row_sep = next((r for r, row in enumerate(grid) if len(set(row)) == 1), None)
    if row_sep is not None:
        a, b = grid[:row_sep], grid[row_sep + 1:]
    else:
        col_sep = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
        a = [row[:col_sep] for row in grid]
        b = [row[col_sep + 1:] for row in grid]
    # Compare matching locations: agreeing pixels take the common dominant color;
    # disagreements become the rare color 3.
    colors_a = {v for row in a for v in row}
    colors_b = {v for row in b for v in row}
    common = colors_a & colors_b
    base = max(common, key=lambda c: sum(row.count(c) for row in a) + sum(row.count(c) for row in b))
    return [[base if x == y else 3 for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
